<?php require '../config/config.php';role(['administrator','pustakawan']);$mo=$_GET['month']??date('Y-m');$q=$pdo->prepare("SELECT COUNT(*) FROM loans WHERE DATE_FORMAT(loan_date,'%Y-%m')=?");$q->execute([$mo]);$pin=$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM loans WHERE returned_at IS NOT NULL AND DATE_FORMAT(returned_at,'%Y-%m')=?");$q->execute([$mo]);$kem=$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM visits WHERE DATE_FORMAT(visit_date,'%Y-%m')=?");$q->execute([$mo]);$kun=$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM loans WHERE late_days>0 AND DATE_FORMAT(COALESCE(returned_at,NOW()),'%Y-%m')=?");$q->execute([$mo]);$ter=$q->fetchColumn();$q=$pdo->prepare("SELECT u.name,COUNT(l.id) total FROM users u JOIN loans l ON l.user_id=u.id WHERE DATE_FORMAT(l.loan_date,'%Y-%m')=? GROUP BY u.id ORDER BY total DESC LIMIT 10");$q->execute([$mo]);$top=$q->fetchAll();?><!doctype html><link rel=stylesheet href=../public/style.css><div class=layout><?php include '../public/nav.php'?><main class=main><h1>📊 Laporan Bulanan</h1><form class=search><input type=month name=month value="<?=e($mo)?>"><button>Tampilkan</button><a class="btn green" href=export_excel.php?month=<?=e($mo)?>>⬇️ Export Excel</a></form><br><div class=cards><div class=card>Peminjaman<div class=num><?=$pin?></div></div><div class=card>Pengembalian<div class=num><?=$kem?></div></div><div class=card>Kunjungan<div class=num><?=$kun?></div></div><div class=card>Keterlambatan<div class=num><?=$ter?></div></div></div><br><div class=card><h3>🏆 Anggota Paling Aktif</h3><table class=table><tr><th>Nama</th><th>Total Peminjaman</th></tr><?php foreach($top as $x):?><tr><td><?=e($x['name'])?></td><td><?=$x['total']?></td></tr><?php endforeach?></table></div></main></div>
